-- Setup
CREATE TABLE queue_demo (id integer PRIMARY KEY);
INSERT INTO queue_demo VALUES (1), (2);

-- Session A
BEGIN;
SELECT id FROM queue_demo WHERE id = 1 FOR UPDATE;

-- Session B
BEGIN;
SELECT id FROM queue_demo
ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED;
ROLLBACK;

-- Session A
ROLLBACK;

CREATE TEMP TABLE processed (event_id text PRIMARY KEY);
CREATE TEMP TABLE totals (value integer NOT NULL);
INSERT INTO totals VALUES (0);

-- Run this statement twice.
WITH accepted AS (
    INSERT INTO processed VALUES ('demo-event')
    ON CONFLICT (event_id) DO NOTHING
    RETURNING event_id
)
UPDATE totals SET value = value + 1
WHERE EXISTS (SELECT 1 FROM accepted);

SELECT value FROM totals;  -- Expected: 1
